    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <script type="text/babel">
      const { useMemo, useState } = React;

      const quizData = [
        {
          id: "q1",
          title: "Which of these are widely used programming languages for building web applications?",
          helpText: "Select every answer that fits. More than one option is correct.",
          choices: ["JavaScript", "Python", "HTML", "Ruby"],
          correctAnswers: ["JavaScript", "Python", "Ruby"],
        },
        {
          id: "q2",
          title: "Which languages are commonly compiled before execution?",
          choices: ["C++", "Go", "Java", "SQL"],
          correctAnswers: ["C++", "Go", "Java"],
        },
        {
          id: "q3",
          title: "Which of these are primarily markup or query languages rather than general-purpose programming languages?",
          choices: ["CSS", "HTML", "SQL", "Rust"],
          correctAnswers: ["CSS", "HTML", "SQL"],
        },
      ];

      function ChoiceOption({ questionId, choice, checked, onToggle }) {
        return (
          <label className={`choice-card${checked ? " selected" : ""}`}>
            <input
              type="checkbox"
              name={`${questionId}-${choice}`}
              checked={checked}
              onChange={() => onToggle(choice)}
            />
            <span className="choice-text">{choice}</span>
          </label>
        );
      }

      function QuizQuestion({ index, question, selectedAnswers, onToggle }) {
        return (
          <div className="form-field">
            <div className="question-row">
              <div>
                <h2 className="question-title">{question.title}</h2>
                {question.helpText ? <p className="help-text">{question.helpText}</p> : null}
              </div>
              <div className="question-number">{index + 1}</div>
            </div>

            <div className="choices">
              {question.choices.map((choice) => (
                <ChoiceOption
                  key={choice}
                  questionId={question.id}
                  choice={choice}
                  checked={selectedAnswers.includes(choice)}
                  onToggle={onToggle}
                />
              ))}
            </div>
          </div>
        );
      }

      function App() {
        const [answers, setAnswers] = useState(() =>
          Object.fromEntries(quizData.map((question) => [question.id, []]))
        );
