        const score = useMemo(() => {
          return quizData.reduce((total, question) => {
            const selected = [...(answers[question.id] || [])].sort();
            const correct = [...question.correctAnswers].sort();
            const isCorrect =
              selected.length === correct.length &&
              selected.every((item, index) => item === correct[index]);
            return total + (isCorrect ? 1 : 0);
          }, 0);
        }, [answers]);

        const toggleChoice = (questionId, choice) => {
          setAnswers((current) => {
            const currentSelections = current[questionId] || [];
            const nextSelections = currentSelections.includes(choice)
              ? currentSelections.filter((item) => item !== choice)
              : [...currentSelections, choice];

            return {
              ...current,
              [questionId]: nextSelections,
            };
          });
        };

        const handleSubmit = (event) => {
          event.preventDefault();
          setSubmitted(true);
        };

        return (
          <main className="page-shell">
