       const quizData = [
         {
           id: "q1",
           title: "Which of these are widely used programming languages for building web applications?",
           helpText: "Select every answer that fits. More than one option is correct.",
           choices: ["JavaScript", "Python", "HTML", "Ruby"],
           correctAnswers: ["JavaScript", "Python", "Ruby"],
         },
         {
           id: "q2",
           title: "Which languages are commonly compiled before execution?",
           choices: ["C++", "Go", "Java", "SQL"],
           correctAnswers: ["C++", "Go", "Java"],
         },
         {
           id: "q3",
           title: "Which of these are primarily markup or query languages rather than general-purpose programming languages?",
           choices: ["CSS", "HTML", "SQL", "Rust"],
           correctAnswers: ["CSS", "HTML", "SQL"],
         },
       ];

       function ChoiceOption({ questionId, choice, checked, onToggle }) {
         return (
           <label className={`choice-card${checked ? " selected" : ""}`}>
             <input
               type="checkbox"
               name={`${questionId}-${choice}`}
               checked={checked}
               onChange={() => onToggle(choice)}
             />
             <span className="choice-text">{choice}</span>
           </label>
         );
       }

       function QuizQuestion({ index, question, selectedAnswers, onToggle }) {
         return (
           <div className="form-field">
             <div className="question-row">
               <div>
                 <h2 className="question-title">{question.title}</h2>
                 {question.helpText ? <p className="help-text">{question.helpText}</p> : null}
               </div>
               <div className="question-number">{index + 1}</div>
             </div>

             <div className="choices">
               {question.choices.map((choice) => (
                 <ChoiceOption
                   key={choice}
                   questionId={question.id}
                   choice={choice}
                   checked={selectedAnswers.includes(choice)}
                   onToggle={onToggle}
                 />
               ))}
             </div>
           </div>
         );
       }

       function App() {
         const [answers, setAnswers] = useState(() =>
           Object.fromEntries(quizData.map((question) => [question.id, []]))
         );
         const [submitted, setSubmitted] = useState(false);

         const score = useMemo(() => {
           return quizData.reduce((total, question) => {
             const selected = [...(answers[question.id] || [])].sort();
             const correct = [...question.correctAnswers].sort();
             const isCorrect =
               selected.length === correct.length &&
               selected.every((item, index) => item === correct[index]);
             return total + (isCorrect ? 1 : 0);
           }, 0);
         }, [answers]);

         const toggleChoice = (questionId, choice) => {
           setAnswers((current) => {
             const currentSelections = current[questionId] || [];
             const nextSelections = currentSelections.includes(choice)
               ? currentSelections.filter((item) => item !== choice)
               : [...currentSelections, choice];

             return {
               ...current,
               [questionId]: nextSelections,
             };
           });
         };

         const handleSubmit = (event) => {
           event.preventDefault();
           setSubmitted(true);
         };

         return (
           <main className="page-shell">
             <section className="hero-card">
               <header className="hero-header">
                 <span className="eyebrow">Interactive quiz</span>
                 <h1>Computer languages knowledge check</h1>
                 <p className="hero-copy">
                   Explore three quick questions about programming, compiled languages, and web
                   technologies. Each question supports multiple selections.
                 </p>
               </header>

               <form className="quiz-form" onSubmit={handleSubmit}>
                 {quizData.map((question, index) => (
                   <QuizQuestion
                     key={question.id}
                     index={index}
                     question={question}
                     selectedAnswers={answers[question.id]}
                     onToggle={(choice) => toggleChoice(question.id, choice)}
                   />
                 ))}

                 <div className="actions">
                   <button className="submit-button" type="submit">
                     Submit quiz
                   </button>

                   {submitted ? (
                     <div className="result-card" aria-live="polite">
                       <strong>
                         Score: {score} / {quizData.length}
                       </strong>
                       <span>Your answers were submitted successfully.</span>
                     </div>
                   ) : null}
                 </div>
               </form>
             </section>
           </main>
         );
       }

       ReactDOM.createRoot(document.getElementById("root")).render(<App />);
     </script>
   </body>
